"""Regenerate ``src/ovid2/web/static/vendor/vega.bundle.min.js``.

The browser bundle (Vega + Vega-Lite + vega-embed) is produced by
``vl-convert-python`` so the Studio preview and the server-side exporters
compile charts with *exactly* the same library versions. Self-hosted for
air-gapped installs (``tests/contract/test_no_third_party_cdn.py``).

Usage: ``python scripts/vendor/build_vega_bundle.py``
"""

from __future__ import annotations

from pathlib import Path

import vl_convert as vlc

OUT = (
    Path(__file__).resolve().parents[2]
    / "src"
    / "ovid2"
    / "web"
    / "static"
    / "vendor"
    / "vega.bundle.min.js"
)


def main() -> int:
    """Write the bundle with a version banner."""
    banner = (
        f"/*! Ovid2 vendored Vega bundle — vega {vlc.get_vega_version()}, "
        f"vega-lite {vlc.get_vegalite_versions()[-1]}, vega-embed {vlc.get_vega_embed_version()}. "
        "BSD-3-Clause (Vega/Vega-Lite/vega-embed, University of Washington Interactive Data Lab). "
        "Generated by scripts/vendor/build_vega_bundle.py via vl-convert-python; do not edit. */\n"
    )
    OUT.write_text(banner + vlc.javascript_bundle(), encoding="utf-8")
    print(f"wrote {OUT} ({OUT.stat().st_size:,} bytes)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
